const VERSION='bdda-algebra-adventure-v2';
let state={person:'Quinn',profiles:{}},saved=true,migrated=false;
function blankProfile(){return {lesson:0,records:lessons.map(()=>({attempts:0,supported:0,unprompted:0,observation:'explored'}))}}
try{
 const raw=localStorage.getItem(VERSION);
 if(raw){const parsed=JSON.parse(raw);if(parsed&&parsed.profiles)state=parsed;}
 else{const old=JSON.parse(localStorage.getItem('bdda-algebra-adventure-v1')||'null');if(old&&old.profiles){
 state.person=old.person;const map=[0,1,2,3,4,6,9,11];
 for(const name of ['Quinn','Reagan','Guest'])if(old.profiles[name]){const prior=old.profiles[name],p=blankProfile();p.lesson=map[prior.lesson]||0;p.legacyCounts=Array.isArray(prior.counts)?prior.counts.slice():[];state.profiles[name]=p;}migrated=true;
 }}
}catch(e){saved=false}
if(!['Quinn','Reagan','Guest'].includes(state.person))state.person='Quinn';
function profile(){let p=state.profiles[state.person];if(!p||!Array.isArray(p.records)||p.records.length!==lessons.length)p=state.profiles[state.person]=blankProfile();return p}
let chapter=0,step=0,practice=null,revealed=0,solved=false,lab={},guidedOpen=false,helpUsed=false,checking=false;
function record(){return profile().records[chapter]}
function save(){try{localStorage.setItem(VERSION,JSON.stringify(state));saved=true}catch(e){saved=false}$('storageNote').textContent=(saved?'Works offline. Each explorer’s progress is saved locally.':'Works offline. Progress cannot be saved in this browser.')+(profile().legacyCounts?' Earlier course counts are preserved as a legacy record, not converted into independent evidence.':'')}
function nav(){$('nav').innerHTML=lessons.map((l,i)=>`<button data-chapter="${i}" class="${i===chapter?'active':''}" ${i===chapter?'aria-current="step"':''}><span class="num">${i===11?'★':i+1}</span><span>${l.title}</span></button>`).join('')}
function deepHTML(l){const d=l.deep;if(!d)return '';return `<details><summary>More detail: a model, the symbols, and another example</summary><h3>Build it, then say it</h3><ol>${d.hands.map(t=>`<li>${t}</li>`).join('')}</ol><h3>What the symbols mean</h3>${d.meaning.map(([title,body])=>`<p><strong>${title}</strong><br>${body}</p>`).join('')}<h3>Another worked example</h3><p class="math">${d.start}</p><ol>${d.worked.map(([eq,why])=>`<li><strong>${eq}</strong><br>${why}</li>`).join('')}</ol></details>`}
function bridgeHTML(l){const b=l.bridge;if(!b)return '';return `<section class="card"><h3>From boxes and bars to algebra</h3><p>The same problem, written two ways. Try the picture first, then reveal the matching algebra.</p><p class="math">${b.problem}</p><div class="bridgeBar" role="img" aria-label="Whole ${b.whole}; parts ${b.parts.join(' and ')}"><div>Whole: ${b.whole}</div><div class="bridgeParts">${b.parts.map(p=>`<span>${p}</span>`).join('')}</div></div><p class="small">A part–whole picture: labels tell you the amounts. Lengths are schematic.</p><div class="bridgeColumns"><div><h4>Box / bar reasoning</h4><ol>${b.school.map(t=>`<li>${t}</li>`).join('')}</ol></div><div><h4>The same reasoning with a letter</h4><details><summary>Show the algebra</summary><ol>${b.algebra.map(t=>`<li>${t}</li>`).join('')}</ol></details></div></div><p><strong>Make the connection:</strong> ${b.connection}</p><details><summary>Check both methods</summary><p>${b.check}</p></details><p class="small">Point to the unknown in the picture and in the equation. What stays the same when we change the writing?</p></section>`}
function sessionHTML(){return `<section class="card tint"><h3>One small adventure today</h3><ol><li><strong>Remember:</strong> tell your grown-up one thing from last time. It is fine to look back.</li><li><strong>Explore:</strong> predict one example step, then try the activity. Use counters or a drawing.</li><li><strong>Try:</strong> work a few problems and explain one answer. A hint is welcome.</li><li><strong>Pause:</strong> stop after about 10–15 minutes, or sooner if you need a break. You do not have to finish an episode today.</li></ol><p class="small">Your place saves for this explorer. Next time, choose “Try a later check” to see what you remember.</p>${chapter===10?'<p><strong>This is the last core episode.</strong> Keep using mixed practice and revisit anything that needs help. The detective episode is an optional puzzle.</p>':''}</section>`}
function render(){guidedOpen=false;$('robotBuddy').classList.remove('hidden');pip('welcome','Hi, '+state.person+'! Take your time and explain what you notice.');$('lesson').classList.remove('hidden');$('guide').style.display='none';$('guideToggle').textContent='Grown-up guide';const l=lessons[chapter];step=0;nav();$('lesson').innerHTML=`<article class="card"><div class="eyebrow">${l.tag}</div><h2>${l.title}</h2><p><strong>Your mission:</strong> ${l.goal}</p><p>${l.text}</p><div class="equation math">${l.start}</div><p class="small">Predict the next step before you reveal it. What should it accomplish?</p><ol class="steps" id="steps"></ol><div class="row"><button class="primary" id="nextStep">Show the next step</button><button id="restartSteps">Start example again</button></div><div class="callout">${l.note}</div>${deepHTML(l)}<details><summary>Talk it through</summary><p>${l.ask}</p><p>Say it, draw it, or use counters. A picture is available when it helps.</p></details></article>${bridgeHTML(l)}${sessionHTML()}<section class="card tint" id="lab"></section><section class="card"><h3>Your turn</h3><p class="small">No timer. A hint is useful practice; a check without a hint is recorded separately. Counts do not prove mastery.</p><div id="practice"></div><p id="counter" class="small"></p><div class="row"><button id="freshCheck">Try the episode checkpoint</button><button id="laterCheck">Try a later check</button></div><p class="small">The episode checkpoint stays the same. A later check generates another question on this topic. Explain your reasoning; remembering an answer is different from understanding it.</p></section><section class="card"><h3>Grown-up observation</h3><p class="small">After an explanation and a fresh check, record what you observed. This is not an automatic grade.</p><label>Evidence <select id="observation"><option value="explored">Explored</option><option value="supported">Practiced with help</option><option value="independent">Shown independently</option><option value="revisited">Revisited later</option></select></label><p id="observationStatus" role="status"></p></section><div class="footer"><button id="prevLesson" ${chapter===0?'disabled':''}>← Previous</button><button class="primary" id="nextLesson" ${chapter===lessons.length-1?'disabled':''}>${chapter===10?'Optional detective →':'Next episode →'}</button></div>`;
$('nextStep').onclick=()=>{if(step<l.steps.length){const [a,b]=l.steps[step++];$('steps').insertAdjacentHTML('beforeend',`<li><strong>${a}</strong>${b}</li>`);$('nextStep').disabled=step===l.steps.length;pip('thinking','Why does that step work?')}};
$('restartSteps').onclick=()=>{step=0;$('steps').innerHTML='';$('nextStep').disabled=false};
$('prevLesson').onclick=()=>go(chapter-1);$('nextLesson').onclick=()=>go(chapter+1);
$('observation').value=record().observation;$('observation').onchange=()=>{record().observation=$('observation').value;save();$('observationStatus').textContent='Observation saved.'};
$('freshCheck').onclick=()=>newPractice(true);$('laterCheck').onclick=()=>newPractice('revisit');renderLab();newPractice();save()}
function go(i){chapter=Math.max(0,Math.min(lessons.length-1,i));profile().lesson=chapter;render()}
$('nav').onclick=e=>{const b=e.target.closest('button');if(b)go(+b.dataset.chapter)};
$('learner').value=state.person;$('learner').onchange=()=>{state.person=$('learner').value;go(profile().lesson||0)};
function controls(groups=false){return `<div class="row"><label>Operation <select id="op"><option value="add">Add</option><option value="sub">Subtract</option>${groups?'<option value="mul">Multiply by</option><option value="div">Divide by</option>':''}</select></label><label>Number <input id="amount" type="number" min="1" max="20" value="2"></label><button class="primary" id="apply">Apply</button><button id="resetLab">Reset</button></div><div id="labFeedback" class="feedback" role="status"></div><ol class="log" id="log"></ol>`}
function renderLab(){const type=lessons[chapter].lab;
if(type==='equality'){
 $('lab').innerHTML='<h3>Same value, different writing</h3><p>Evaluate each side. Does the equality hold?</p><div id="equalityQuestion" class="equation math"></div><div class="row"><button id="eqYes">True</button><button id="eqNo">False</button><button id="eqNew">New comparison</button></div><div id="labFeedback" class="feedback" role="status"></div>';
 const next=()=>{const a=rand(1,8),b=rand(1,5),d=rand(0,1);lab={left:a+b,right:a+b+d};$('equalityQuestion').textContent=`${a} + ${b} = ${a+b+d}`};next();$('eqNew').onclick=next;for(const [id,guess] of [['eqYes',true],['eqNo',false]])$(id).onclick=()=>{$('labFeedback').textContent=`Left: ${lab.left}. Right: ${lab.right}. `+((lab.left===lab.right)===guess?'Your judgment works.':'Compare the two values again.')};return;
}
if(type==='balance'){
 lab={left:10,right:10,history:[]};$('lab').innerHTML=`<h3>Balance playground</h3><p>Predict, try, then explain. Repair a one-sided change.</p><div id="balanceView"></div><label>Change <select id="target"><option value="both">Both sides</option><option value="left">Left only</option><option value="right">Right only</option></select></label>${controls()}<button id="undoLab">Undo last move</button>`;drawBalance();$('apply').onclick=balanceMove;$('undoLab').onclick=()=>{const prev=lab.history.pop();if(prev){Object.assign(lab,prev);$('log').lastElementChild?.remove();drawBalance()}};
}else if(type==='solve'||type==='groups'){
 lab={a:lessons[chapter].eq[0],b:lessons[chapter].eq[1],c:lessons[chapter].eq[2],original:[...lessons[chapter].eq]};$('lab').innerHTML=`<h3>${type==='groups'?'Equal amounts, then sharing':'You control the equation'}</h3>${type==='groups'?'<p>First say what x + x and 2x mean. Two bags hold the SAME number of counters. Pause here if you need to.</p>':''}<p>Apply an operation to BOTH sides. Leave x alone.</p><div class="equation math" id="solveView"></div>${controls(chapter>=5)}<p class="small">This activity uses whole-number coefficients and constants from −200 to 200. Its limits are not rules for all algebra.</p>`;drawSolve();$('apply').onclick=solveMove;
}else if(type==='mystery'){
 $('lab').innerHTML='<h3>One number, two names</h3><div class="equation math">□ = 3 + 2<br>x = 3 + 2</div><label>Try x = <input id="mysteryValue" type="number" value="1"></label><button id="testMystery">Replace x and check</button><div id="labFeedback" class="feedback" role="status"></div>';$('testMystery').onclick=()=>{const raw=$('mysteryValue').value,n=Number(raw);$('labFeedback').textContent=raw.trim()===''?'Enter a number first.':`${n} ${n===5?'=':'≠'} 3 + 2. `+(n===5?'Five works!':'Find a number equal to five.')};return;
}else if(type==='substitute'){
 $('lab').innerHTML='<h3>Known x → find B</h3><p>Each slider position starts a NEW example. Within that example, x keeps one value.</p><label>Known x <input type="range" id="xRange" min="0" max="10" value="3"></label><div id="subView"></div><p>Without a known x, B = 2 + x allows many pairs. Try x = 1, then x = 2.</p>';drawSub();$('xRange').oninput=drawSub;return;
}else if(type==='compare'){
 $('lab').innerHTML='<h3>Read a comparison</h3><p>Blue has two MORE than red. Matching bars show matching amounts.</p><div class="bars"><p>Red: <span class="part">R</span></p><p>Blue: <span class="part">R</span><span class="part extra">+ 2</span></p></div><div class="row"><button id="compareRight">B = R + 2</button><button id="compareWrong">R = B + 2</button></div><div id="labFeedback" class="feedback" role="status"></div>';$('compareRight').onclick=()=>{$('labFeedback').textContent='Yes. Start with the smaller red count, then add two to get blue.'};$('compareWrong').onclick=()=>{$('labFeedback').textContent='That would say RED has two more. Our story says BLUE has two more.'};return;
}else if(type==='story'){
 lab={c:null};$('lab').innerHTML='<h3>Solve the unknown bars</h3><p>Thirteen total; five more adults than children. Each green part is the same unknown amount.</p><div id="storyView"></div><label>Try the child count <input id="children" type="number" min="0" step="1"></label><div class="row"><button id="checkStory">Check both clues</button><button id="revealStory">Show a bar solution</button></div><div id="labFeedback" class="feedback" role="status"></div><details><summary>After the bars: connect the equations</summary><p>A = C + 5 and A + C = 13. Replace the whole A: (C + 5) + C = 13. This becomes 2C + 5 = 13. Subtract five, then divide by two. C = 4 and A = 9.</p></details>';drawStory();$('checkStory').onclick=()=>{const raw=$('children').value,c=Number(raw);if(raw.trim()===''||!Number.isInteger(c)||c<0||c>100){$('labFeedback').textContent='Try a whole-number count from 0 to 100.';return}lab.c=c;drawStory();$('labFeedback').textContent=`Total: ${c} + ${c+5} = ${2*c+5}. Difference: ${c+5} − ${c} = 5. `+(c===4?'Both clues fit!':'The difference fits; the total must be thirteen. Try again.')};$('revealStory').onclick=()=>{lab.c=4;drawStory();$('labFeedback').textContent='Remove five extras from thirteen. Eight remain for two equal parts: four in each. C = 4, A = 9. Now check both clues.'};return;
}else if(type==='detective'){
 $('lab').innerHTML='<h3>Can the leftovers share equally?</h3><label>Total people <input id="total" type="number" min="5" max="30" value="12"></label><div id="detectView" class="feedback"></div>';drawDetect();$('total').oninput=drawDetect;return;
}
$('resetLab').onclick=renderLab;
}
const fmt=n=>Number.isInteger(n)?String(n):String(Math.round(n*1000)/1000);
function drawBalance(){const equal=lab.left===lab.right;$('balanceView').innerHTML=`<div class="pans"><div class="pan" style="transform:translateY(${lab.left>lab.right?8:0}px)"><div class="small">LEFT</div><div class="math">${fmt(lab.left)}</div><div class="tokens">${'<i class="token"></i>'.repeat(Math.min(30,Math.floor(lab.left)))}</div></div><div class="math" aria-label="${equal?'equals':'does not equal'}">${equal?'=':'≠'}</div><div class="pan" style="transform:translateY(${lab.right>lab.left?8:0}px)"><div class="small">RIGHT</div><div class="math">${fmt(lab.right)}</div><div class="tokens">${'<i class="token"></i>'.repeat(Math.min(30,Math.floor(lab.right)))}</div></div></div><p class="small">${equal?'Same value: the equation is true.':'Different values: this is not an equality.'} Dots are counters (up to 30 per side).</p>`}
function operation(v,op,n){return op==='add'?v+n:op==='sub'?v-n:op==='mul'?v*n:v/n}
function getMove(){const n=Number($('amount').value),op=$('op').value;if(!Number.isInteger(n)||n<1||n>20){$('labFeedback').textContent='Use a whole number from 1 to 20. Zero is not a solving move here.';return null}return {n,op}}
function balanceMove(){const m=getMove();if(!m)return;const t=$('target').value,L=t==='right'?lab.left:operation(lab.left,m.op,m.n),R=t==='left'?lab.right:operation(lab.right,m.op,m.n);if(L<0||R<0||L>100||R>100||!Number.isInteger(L)||!Number.isInteger(R)){$('labFeedback').textContent='For this counter playground, keep each amount a whole number from 0 to 100. Try a different move.';return}lab.history.push({left:lab.left,right:lab.right});lab.left=L;lab.right=R;drawBalance();$('log').insertAdjacentHTML('beforeend',`<li>${m.op==='add'?'Add':m.op==='sub'?'Subtract':m.op==='mul'?'Multiply by':'Divide by'} ${m.n}; ${t} side${t==='both'?'s':''} → ${L} ${L===R?'=':'≠'} ${R}</li>`);$('labFeedback').textContent=L===R?'The values match! Both sides are equal.':'The values do not match. Can you repair the equality?'}
function expr(a,b){return (a===1?'x':`${fmt(a)}x`)+(b>0?` + ${fmt(b)}`:b<0?` − ${fmt(-b)}`:'')}
function drawSolve(){$('solveView').textContent=`${expr(lab.a,lab.b)} = ${fmt(lab.c)}`}
function solveMove(){const m=getMove();if(!m)return;let {a,b,c}=lab;const before=`${expr(a,b)} = ${c}`;if(m.op==='add'||m.op==='sub'){b=operation(b,m.op,m.n);c=operation(c,m.op,m.n)}else{a=operation(a,m.op,m.n);b=operation(b,m.op,m.n);c=operation(c,m.op,m.n)}if([a,b,c].some(v=>!Number.isInteger(v)||v < -200||v>200)||a<=0){$('labFeedback').textContent='That move is outside this beginner playground. Keep whole-number terms in range and a positive group count. Try undoing the added amount, or dividing every term by the same factor.';return}Object.assign(lab,{a,b,c});drawSolve();const symbol={add:'+',sub:'−',mul:'×',div:'÷'}[m.op];$('log').insertAdjacentHTML('beforeend',`<li>${before}; ${symbol} ${m.n} on both sides → ${expr(a,b)} = ${c}</li>`);if(a===1&&b===0){const [oa,ob,oc]=lab.original;$('labFeedback').textContent=`Solved: x = ${c}. Check the original: ${expr(oa,ob).replaceAll('x','('+c+')')} = ${oc}. Both sides match!`}else $('labFeedback').textContent='Equality preserved. What can you undo next to leave x alone?'}
