if(ch===1){q=`Start with ${x+b} = ${x+b}. Subtract ${b} from BOTH sides. What is each side?`;answers=[x];labels=['Each side'];hint='Do the same subtraction twice.';steps=[`${x+b} − ${b} = ${x+b} − ${b}`,`${x} = ${x}`];meta={kind:'both',start:x+b,b}}
if(ch===2){q=`x = ${a} + ${b}`;answers=[a+b];hint='x is the value of the whole sum.';steps=[`x = ${a+b}`,`Check: ${a+b} = ${a} + ${b}.`];meta={kind:'sum',a,b}}
if(ch===3||ch===4||ch===5||ch===7){const coef=(ch===5||ch===7)?a:1,constant=ch===4?-b:ch===5?0:b;if(ch===4)x+=b;const total=coef*x+constant,expression=expr(coef,constant);q=ch===3?[`${expression} = ${total}`,`${b} + x = ${total}`,`${total} = ${expression}`][rand(0,2)]:`${expression} = ${total}`;answers=[x];hint=constant===0?`Divide BOTH sides by ${coef}.`:constant<0?`Add ${-constant} to BOTH sides.`:`Subtract ${constant} from BOTH sides.`;steps=[];if(constant!==0)steps.push(`${expression} = ${total}; ${constant<0?'add '+(-constant):'subtract '+constant} on both sides.`,`${expr(coef,0)} = ${coef*x}`);if(coef!==1)steps.push(`Divide BOTH sides by ${coef}: x = ${x}.`);else steps.push(`x = ${x}.`);steps.push(`Check: ${coef} × ${x} ${constant<0?'− '+(-constant):'+ '+constant} = ${total}.`);meta={kind:'equation',a:coef,b:constant,c:total}}
