function newPractice(check=false){checking=check;practice=check===true?lessons[chapter].check:makeProblem(chapter);revealed=0;solved=false;helpUsed=false;const p=practice;
$('practice').innerHTML=`<div class="eyebrow">${check==='revisit'?'Later check · explain what you remember':check?'Episode checkpoint · explain your check':'Practice'}</div><div class="equation">${p.q}</div><form id="answerForm"><div class="row">${p.labels.map((label,i)=>`<label>${label} ${typeof p.answers[i]==='string'?`<select id="answer${i}" required><option value="">Choose…</option>${p.meta?.kind==='relation'?`<option>B = R + ${p.meta.b}</option><option>R = B + ${p.meta.b}</option>`:'<option value="yes">Yes</option><option value="no">No</option>'}</select>`:`<input id="answer${i}" type="number" step="any" required autocomplete="off">`}</label>`).join('')}<button class="primary" type="submit">Check answer</button></div></form><div id="answerFeedback" class="feedback" role="status">What do you think? Try an answer.</div><div class="row"><button id="hint">Give me a hint</button><button id="solution">One solution step</button><button id="fresh">New problem</button></div><p id="hintText" class="small"></p><ol class="steps" id="solutionSteps"></ol>`;
